insert into public.instrumente (id, thema_id, name, begruendung, evidenz, beleg_studie_url, ebene, entspricht, ki_entwurf, entwurf_herkunft) values
  (8387, 33, 'Verbindliches Handyverbot im Schulalltag bis zur Mittelstufe (Land)', 'Dafür: In England, Florida und Indien stiegen die Noten leicht bis moderat, Ablenkung sank. Dagegen: In Florida, Schweden und England fanden Studien keine Effekte auf Noten oder Wohlbefinden; Abendnutzung bleibt unberührt.', 'gemischt', 'https://world-education-blog.org/2025/12/15/are-phone-bans-working/', 'land', null, true, 'blind'),
  (8388, 33, 'Handyverbot oder bildschirmfreie Klassen in der Grundschule (Land)', 'Weniger Ablenkung möglich, doch Effekte zeigten sich vor allem an weiterführenden Schulen mit hohem Smartphone-Besitz; in der Grundschule ist die Nutzung ohnehin geringer. Studien zu Handyregeln uneinheitlich.', 'gemischt', 'https://world-education-blog.org/2025/12/15/are-phone-bans-working/', 'land', null, true, 'blind'),
  (8389, 33, 'Medienbildung in Schule und außerschulischen Angeboten stärken (Land)', 'Schulische Programme senkten problematische Nutzung deutlich, Bildschirmzeit kaum (Metaanalyse, 34 Studien, Verzerrung möglich). Allgemeine Medienbildung setzt nur indirekt an der Begleitung durch Eltern an.', 'gemischt', 'https://europepmc.org/article/MED/40549948', 'land', null, true, 'blind'),
  (8390, 33, 'Schulische Prävention von Mediensucht und Mediengefahren (Land)', 'Gezielte schulische Prävention senkte problematische Nutzung deutlich (d = 1,47), Bildschirmzeit kaum (d = 0,15); Publikationsverzerrung möglich. Setzt bei den Kindern an, nicht direkt bei der Begleitung durch Eltern.', 'gemischt', 'https://europepmc.org/article/MED/40549948', 'land', null, true, 'blind'),
  (8391, 33, 'Fachkräfte in Medienbildung qualifizieren, Zentren und Teams ausbauen (Land)', 'Geschulte Fachkräfte und Zentren können Medienbildung tragen; die Wirkung auf die Mediennutzung der Kinder läuft nur über den Unterricht und ist kaum untersucht.', 'offen', null, 'land', null, true, 'blind'),
  (8392, 33, 'Eltern durch Beratung und Bildungsangebote in der Medienerziehung unterstützen (Land)', 'Setzt direkt bei den Eltern an; Programme mit Elternbeteiligung senkten problematische Nutzung stärker. Belastbare Daten zu reinen Elternangeboten fehlen, und es erreichen vor allem interessierte Eltern.', 'gemischt', 'https://europepmc.org/article/MED/40549948', 'land', null, true, 'blind'),
  (8393, 33, 'Eltern mit Informationen zur Mediennutzung versorgen (Land)', 'Leicht und schnell umsetzbar; Information erreicht aber nur, wer sie nutzt, und die Wirkung auf die Begleitung durch Eltern ist kaum untersucht.', 'offen', null, 'land', null, true, 'blind'),
  (8394, 33, 'Digital Services Act umsetzen mit Schwerpunkt Jugendschutz (Bund)', 'Der DSA verpflichtet Plattformen zu Risikoprüfungen auch zu Minderjährigen; die Wirkung auf Likes- und Belohnungsdesign ist bisher kaum untersucht. Umsetzung durch den Bund ist möglich.', 'offen', null, 'bund', null, true, 'blind'),
  (8395, 33, 'Medienkompetenz in Schulen und Lehrplänen stärken (Bund)', 'Schulische Medienbildung wirkt gegen problematische Nutzung, aber kaum auf die Bildschirmzeit; Schulen und Lehrpläne sind Ländersache, der Bund kann nur Anreize setzen.', 'gemischt', 'https://europepmc.org/article/MED/40549948', 'bund', null, true, 'blind')
