  (8396, 33, 11, null, 'Kinder- und Jugendschutz im Netz einschließlich sozialer Medien gewährleisten; bei der Umsetzung des Digital Services Act Jugend- und Medienschutz betonen.', '{3301}', 8394, 1, 3, null, 'Der DSA verpflichtet Plattformen zu Risikoprüfungen auch zu Minderjährigen; die Wirkung auf Likes- und Belohnungsdesign ist bisher kaum untersucht. Umsetzung durch den Bund ist möglich.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=41', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8397, 33, 11, 'BE', 'Medienkompetenz wird an allen Schulen verbindlicher Bestandteil des Unterrichts; Schülerinnen und Schüler lernen kritischen und verantwortungsvollen Umgang mit Medien.', '{3303}', 8389, 1, 3, null, 'Schulische Programme senkten problematische Nutzung deutlich, Bildschirmzeit kaum (Metaanalyse, 34 Studien, Verzerrung möglich). Allgemeine Medienbildung setzt nur indirekt an der Begleitung durch Eltern an.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=63', 'https://europepmc.org/article/MED/40549948', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8398, 33, 11, 'BE', 'Lehrkräfte werden im Bereich Digitalisierung und Medienbildung verbindlich und systematisch qualifiziert.', '{3303}', 8391, 1, 3, null, 'Geschulte Fachkräfte und Zentren können Medienbildung tragen; die Wirkung auf die Mediennutzung der Kinder läuft nur über den Unterricht und ist kaum untersucht.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=60', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8399, 33, 11, 'MV', 'Landeseinheitliches Verbot privater Smartphone-Nutzung im Unterricht und auf dem Schulgelände bis Klasse zehn.', '{3302}', 8387, 2, 3, null, 'Dafür: In England, Florida und Indien stiegen die Noten leicht bis moderat, Ablenkung sank. Dagegen: In Florida, Schweden und England fanden Studien keine Effekte auf Noten oder Wohlbefinden; Abendnutzung bleibt unberührt.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=53', 'https://world-education-blog.org/2025/12/15/are-phone-bans-working/', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8400, 33, 11, 'MV', 'Altersgerechte Mediensensibilisierung über die Gefahren digitaler und sozialer Medien in Kindergarten und Grundschule.', '{3303}', 8390, 2, 3, null, 'Gezielte schulische Prävention senkte problematische Nutzung deutlich (d = 1,47), Bildschirmzeit kaum (d = 0,15); Publikationsverzerrung möglich. Setzt bei den Kindern an, nicht direkt bei der Begleitung durch Eltern.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=53', 'https://europepmc.org/article/MED/40549948', 'gemischt', '2026-10-06', false, true, 'blind'),
