  (8402, 33, 11, 'ST', 'Medienbildung in der Kita altersgerecht und mit pädagogischer Begleitung einführen.', '{3303}', 8389, 1, 3, null, 'Schulische Programme senkten problematische Nutzung deutlich, Bildschirmzeit kaum (Metaanalyse, 34 Studien, Verzerrung möglich). Allgemeine Medienbildung setzt nur indirekt an der Begleitung durch Eltern an.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=49', 'https://europepmc.org/article/MED/40549948', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8403, 33, 11, 'ST', 'In Schulen Projekte und Unterrichtseinheiten, die die kritische Reflexionsfähigkeit im Umgang mit digitalen Medien stärken.', '{3303}', 8389, 1, 3, null, 'Schulische Programme senkten problematische Nutzung deutlich, Bildschirmzeit kaum (Metaanalyse, 34 Studien, Verzerrung möglich). Allgemeine Medienbildung setzt nur indirekt an der Begleitung durch Eltern an.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=22', 'https://europepmc.org/article/MED/40549948', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8404, 33, 12, null, 'Jugendschutz im Netz stärken, unter anderem durch wirksame Möglichkeiten zur Altersverifikation.', '{3301}', null, 1, 2, null, 'Verifikation kann Altersgrenzen durchsetzen, ersetzt aber keine Designregeln; technische Umsetzung hängt an EU-Lösungen und Datenschutz.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=45', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8405, 33, 12, null, 'Plattformen müssen ihre Algorithmen zur Inhaltsdarstellung offenlegen und auf manipulative Praktiken prüfen lassen.', '{3301}', null, 1, 1, null, 'Transparenz und Prüfung machen Empfehlungsdesign sichtbar, verbieten es aber nicht; Wirkung auf Kinder kaum untersucht. Plattformregeln setzt weitgehend die EU (DSA).', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=50', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8406, 33, 12, 'BE', 'Handyverbot an allen Grundschulen durchsetzen, begründet mit Gesundheits- und Kinderschutz.', '{3302}', 8388, 1, 3, null, 'Weniger Ablenkung möglich, doch Effekte zeigten sich vor allem an weiterführenden Schulen mit hohem Smartphone-Besitz; in der Grundschule ist die Nutzung ohnehin geringer. Studien zu Handyregeln uneinheitlich.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=41', 'https://world-education-blog.org/2025/12/15/are-phone-bans-working/', 'gemischt', '2026-10-06', false, true, 'blind'),
