  (8425, 33, 14, 'BE', 'Elternarbeit zur Aufklärung der Kinder über Medienkonsum und Gefahren im Netz stärken.', '{3303}', 8392, 2, 3, null, 'Setzt direkt bei den Eltern an; Programme mit Elternbeteiligung senkten problematische Nutzung stärker. Belastbare Daten zu reinen Elternangeboten fehlen, und es erreichen vor allem interessierte Eltern.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=17', 'https://europepmc.org/article/MED/40549948', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8426, 33, 14, 'BE', 'Eltern und Fachkräfte mit mehr Informationen zur Mediennutzung von Kindern und Jugendlichen versorgen.', '{3303}', 8393, 1, 3, null, 'Leicht und schnell umsetzbar; Information erreicht aber nur, wer sie nutzt, und die Wirkung auf die Begleitung durch Eltern ist kaum untersucht.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=17', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8427, 33, 14, 'MV', 'Eltern durch verständliche, freiwillige, wissenschaftsbasierte Informationen zu Mediennutzung, Bildschirmzeiten und digitaler Sicherheit stärken.', '{3303}', 8393, 1, 3, null, 'Leicht und schnell umsetzbar; Information erreicht aber nur, wer sie nutzt, und die Wirkung auf die Begleitung durch Eltern ist kaum untersucht.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=84', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8428, 33, 14, 'MV', 'Medienbildung und kritischen, selbstbestimmten Umgang mit neuen Medien für alle Kinder und Jugendlichen als verbindlichen Lerninhalt festlegen.', '{3303}', 8389, 1, 3, null, 'Schulische Programme senkten problematische Nutzung deutlich, Bildschirmzeit kaum (Metaanalyse, 34 Studien, Verzerrung möglich). Allgemeine Medienbildung setzt nur indirekt an der Begleitung durch Eltern an.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=98', 'https://europepmc.org/article/MED/40549948', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8429, 33, 14, 'ST', 'Angebote der Medienbildung weiter ausbauen und Eltern bei der digitalen Erziehung durch Unterstützungsangebote helfen.', '{3303}', 8392, 2, 3, null, 'Setzt direkt bei den Eltern an; Programme mit Elternbeteiligung senkten problematische Nutzung stärker. Belastbare Daten zu reinen Elternangeboten fehlen, und es erreichen vor allem interessierte Eltern.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=26', 'https://europepmc.org/article/MED/40549948', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8430, 33, 15, 'BE', 'Grundschulen bildschirmfrei halten und dort Smartphones verbieten; an weiterführenden Schulen das Mitführen von Smartphones restriktiver handhaben.', '{3302}', 8388, 1, 3, null, 'Weniger Ablenkung möglich, doch Effekte zeigten sich vor allem an weiterführenden Schulen mit hohem Smartphone-Besitz; in der Grundschule ist die Nutzung ohnehin geringer. Studien zu Handyregeln uneinheitlich.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=30', 'https://world-education-blog.org/2025/12/15/are-phone-bans-working/', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8431, 33, 15, 'MV', 'Private Handynutzung im Schulalltag bis zur 7. Klasse per Verordnung unterbinden, Ausnahmen nur bei Notfällen oder nach Rücksprache mit der Lehrkraft.', '{3302}', 8387, 2, 3, null, 'Dafür: In England, Florida und Indien stiegen die Noten leicht bis moderat, Ablenkung sank. Dagegen: In Florida, Schweden und England fanden Studien keine Effekte auf Noten oder Wohlbefinden; Abendnutzung bleibt unberührt.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=31', 'https://world-education-blog.org/2025/12/15/are-phone-bans-working/', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8432, 33, 15, 'ST', 'Smartphone-Nutzung an Schulen bis einschließlich Klasse 10 untersagen.', '{3302}', 8387, 2, 3, null, 'Dafür: In England, Florida und Indien stiegen die Noten leicht bis moderat, Ablenkung sank. Dagegen: In Florida, Schweden und England fanden Studien keine Effekte auf Noten oder Wohlbefinden; Abendnutzung bleibt unberührt.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=79', 'https://world-education-blog.org/2025/12/15/are-phone-bans-working/', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8433, 33, 16, null, 'Medien- und Datenschutzkompetenz von Kindern und Jugendlichen möglichst früh fördern.', '{3303}', null, 1, 2, null, 'Frühe Förderung ist sinnvoll, nennt aber keinen Weg; Schulen sind Ländersache, der Bund kann mit Programmen und Geld beitragen. Wirkung auf die Bildschirmzeit gering.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=39', 'https://europepmc.org/article/MED/40549948', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8434, 33, 16, null, 'EU-Gesetz über digitale Dienste zügig in nationales Recht überführen.', '{3301}', 8394, 1, 3, null, 'Der DSA verpflichtet Plattformen zu Risikoprüfungen auch zu Minderjährigen; die Wirkung auf Likes- und Belohnungsdesign ist bisher kaum untersucht. Umsetzung durch den Bund ist möglich.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=57', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8435, 33, 16, 'BE', 'Medienbildung inklusive Mediensuchtprävention ab der Grundschule verbindlich in Rahmenlehrplänen und schulinternen Curricula verankern.', '{3303}', 8390, 2, 3, null, 'Gezielte schulische Prävention senkte problematische Nutzung deutlich (d = 1,47), Bildschirmzeit kaum (d = 0,15); Publikationsverzerrung möglich. Setzt bei den Kindern an, nicht direkt bei der Begleitung durch Eltern.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=165', 'https://europepmc.org/article/MED/40549948', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8436, 33, 16, 'BE', 'Schulgemeinschaften in Medienbildung schulen und Ressourcen für Elternarbeit ausbauen, um Eltern früh einzubeziehen.', '{3303}', 8392, 2, 3, null, 'Setzt direkt bei den Eltern an; Programme mit Elternbeteiligung senkten problematische Nutzung stärker. Belastbare Daten zu reinen Elternangeboten fehlen, und es erreichen vor allem interessierte Eltern.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=165', 'https://europepmc.org/article/MED/40549948', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8437, 33, 16, 'BE', 'Medienkompetenzzentren in allen Bezirken gut ausstatten, kostenfreie begleitete Angebote und regelmäßige Schulungen für Fachkräfte schaffen, für junge Menschen, Eltern und Fachkräfte.', '{3303}', 8392, 2, 3, null, 'Setzt direkt bei den Eltern an; Programme mit Elternbeteiligung senkten problematische Nutzung stärker. Belastbare Daten zu reinen Elternangeboten fehlen, und es erreichen vor allem interessierte Eltern.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=178', 'https://europepmc.org/article/MED/40549948', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8438, 33, 16, 'BE', 'Haushaltsmittel für Medienkompetenzbildung durch Freie Träger bereitstellen, entwickelt mit jungen Menschen für junge Menschen.', '{3303}', 8389, 1, 3, null, 'Schulische Programme senkten problematische Nutzung deutlich, Bildschirmzeit kaum (Metaanalyse, 34 Studien, Verzerrung möglich). Allgemeine Medienbildung setzt nur indirekt an der Begleitung durch Eltern an.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=247', 'https://europepmc.org/article/MED/40549948', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8439, 33, 16, 'BE', 'Verbindliche Fort- und Weiterbildungsangebote für Schulbeschäftigte zu Medienbildung.', '{3303}', 8391, 1, 3, null, 'Geschulte Fachkräfte und Zentren können Medienbildung tragen; die Wirkung auf die Mediennutzung der Kinder läuft nur über den Unterricht und ist kaum untersucht.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=229', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8440, 33, 16, 'BE', 'Handyfreier Schultag bis Jahrgangsstufe 9 als Grundsatz, solange die Schulgemeinschaft keine andere Regelung beschließt.', '{3302}', 8387, 2, 3, null, 'Dafür: In England, Florida und Indien stiegen die Noten leicht bis moderat, Ablenkung sank. Dagegen: In Florida, Schweden und England fanden Studien keine Effekte auf Noten oder Wohlbefinden; Abendnutzung bleibt unberührt.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=167', 'https://world-education-blog.org/2025/12/15/are-phone-bans-working/', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8441, 33, 16, 'MV', 'Medienbildung auf allen Ebenen ausbauen: in der Schule, außerschulisch und für Erwachsene.', '{3303}', 8389, 1, 3, null, 'Schulische Programme senkten problematische Nutzung deutlich, Bildschirmzeit kaum (Metaanalyse, 34 Studien, Verzerrung möglich). Allgemeine Medienbildung setzt nur indirekt an der Begleitung durch Eltern an.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=27', 'https://europepmc.org/article/MED/40549948', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8442, 33, 16, 'MV', 'Das medienpädagogische Zentrum personell ausbauen, um Unterrichtsangebote zur Medienbildung zu stärken.', '{3303}', 8391, 1, 3, null, 'Geschulte Fachkräfte und Zentren können Medienbildung tragen; die Wirkung auf die Mediennutzung der Kinder läuft nur über den Unterricht und ist kaum untersucht.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=5', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8443, 33, 16, 'ST', 'Landesprogramm zur Stärkung der Medienkompetenz und digitalen Bildung an Schulen.', '{3303}', 8389, 1, 3, null, 'Schulische Programme senkten problematische Nutzung deutlich, Bildschirmzeit kaum (Metaanalyse, 34 Studien, Verzerrung möglich). Allgemeine Medienbildung setzt nur indirekt an der Begleitung durch Eltern an.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=74', 'https://europepmc.org/article/MED/40549948', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8444, 33, 17, null, 'Gesetz für soziale Medien nach australischem Vorbild, damit Kinder weniger in der virtuellen Welt verschwinden.', '{3301}', null, 2, 1, null, 'Altersgrenze setzt direkt am Zugang zu Likes- und Belohnungssystemen an; Erfahrungen aus Australien sind sehr jung, Umgehung möglich. Nationale Regelung stößt an EU-Recht und Länder-Jugendmedienschutz.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=24', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8445, 33, 17, null, 'Handys und Tablets mindestens bis zum Ende der Grundschule aus den Klassenzimmern verbannen, danach möglichst wenig im Unterricht einsetzen.', '{3302}', null, 1, 1, null, 'Weniger Ablenkung im Unterricht, Abendnutzung und Schlaf bleiben unberührt; Studien uneinheitlich. Schulrecht ist Ländersache, der Bund kann nur Anreize setzen.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=24', 'https://world-education-blog.org/2025/12/15/are-phone-bans-working/', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8446, 33, 17, 'BE', 'Grundschulklassen ohne Bildschirme einrichten, um Aufmerksamkeit, Gedächtnis und Lesekompetenz zu fördern.', '{3302}', 8388, 1, 3, null, 'Weniger Ablenkung möglich, doch Effekte zeigten sich vor allem an weiterführenden Schulen mit hohem Smartphone-Besitz; in der Grundschule ist die Nutzung ohnehin geringer. Studien zu Handyregeln uneinheitlich.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=16', 'https://world-education-blog.org/2025/12/15/are-phone-bans-working/', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8447, 33, 17, 'BE', 'Smartphones im Unterricht grundsätzlich nicht nutzen und vor dem Unterricht wegschließen.', '{3302}', null, 1, 3, null, 'Wegschließen verringert Ablenkung in den Stunden, nicht aber die Nutzung in Pausen oder abends. Studien zu Handyregeln uneinheitlich.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=16', 'https://world-education-blog.org/2025/12/15/are-phone-bans-working/', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8448, 33, 17, 'BE', 'Verbindlichen digitalen Führerschein mit Nachweis von Medien-, Datenschutz- und Informationskenntnissen bis Ende Klasse 10 einführen.', '{3303}', 8389, 1, 3, null, 'Schulische Programme senkten problematische Nutzung deutlich, Bildschirmzeit kaum (Metaanalyse, 34 Studien, Verzerrung möglich). Allgemeine Medienbildung setzt nur indirekt an der Begleitung durch Eltern an.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=16', 'https://europepmc.org/article/MED/40549948', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8449, 33, 17, 'MV', 'Familienbildungs- und Beratungsangebote ausbauen, die Eltern in der Medienerziehung stärken und Orientierung im digitalen Alltag geben.', '{3303}', 8392, 2, 3, null, 'Setzt direkt bei den Eltern an; Programme mit Elternbeteiligung senkten problematische Nutzung stärker. Belastbare Daten zu reinen Elternangeboten fehlen, und es erreichen vor allem interessierte Eltern.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=12', 'https://europepmc.org/article/MED/40549948', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8450, 33, 17, 'MV', 'Präventionsangebote für Kinder und Jugendliche ausbauen, die auch Medienkompetenz stärken.', '{3303}', 8389, 1, 3, null, 'Schulische Programme senkten problematische Nutzung deutlich, Bildschirmzeit kaum (Metaanalyse, 34 Studien, Verzerrung möglich). Allgemeine Medienbildung setzt nur indirekt an der Begleitung durch Eltern an.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=61', 'https://europepmc.org/article/MED/40549948', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8451, 33, 17, 'MV', 'Medienkompetenz an weiterführenden Schulen vermitteln, in der Grundschule ohne digitale Endgeräte lernen.', '{3303}', 8389, 1, 3, null, 'Schulische Programme senkten problematische Nutzung deutlich, Bildschirmzeit kaum (Metaanalyse, 34 Studien, Verzerrung möglich). Allgemeine Medienbildung setzt nur indirekt an der Begleitung durch Eltern an.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=47', 'https://europepmc.org/article/MED/40549948', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8452, 33, 17, 'ST', 'Verbindliches Smartphone-Verbot im Schulalltag, um Ablenkung und digitale Abhängigkeiten zu verringern.', '{3302}', 8387, 2, 3, null, 'Dafür: In England, Florida und Indien stiegen die Noten leicht bis moderat, Ablenkung sank. Dagegen: In Florida, Schweden und England fanden Studien keine Effekte auf Noten oder Wohlbefinden; Abendnutzung bleibt unberührt.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=45', 'https://world-education-blog.org/2025/12/15/are-phone-bans-working/', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8595, 33, 18, null, 'Manipulative Gestaltung digitaler Angebote (Dark Patterns) und algorithmische Beeinflussung werden gesetzlich geregelt.', '{3301}', null, 2, 1, null, 'Setzt direkt an belohnungs- und suchtfördernden Designs an, die eine Prüfung trotz DSA auf allen großen Plattformen fand. Dagegen: Wirkung auf die Nutzung kaum untersucht; DSA und Verbraucherrecht sind EU-weit harmonisiert, nationale Regeln kaum möglich.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=27', 'https://www.vzbv.de/en/social-media-platforms-failing-adequately-protect-minors', 'offen', '2026-10-07', false, true, 'blind'),
  (8596, 33, 18, null, 'Aufsicht über digitale Dienste einschließlich des digitalen Jugendschutzes wird bei der Bundesnetzagentur gebündelt.', '{3301}', 8394, 1, 3, null, 'Der DSA verpflichtet Plattformen zu Risikoprüfungen auch zu Minderjährigen; die Wirkung auf Likes- und Belohnungsdesign ist bisher kaum untersucht. Umsetzung durch den Bund ist möglich.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=25', null, 'offen', '2026-10-07', false, true, 'blind'),
  (8597, 33, 18, null, 'Schulungen für Eltern zu Chancen und Risiken der Digitalisierung.', '{3303}', null, 2, 2, null, 'Setzt direkt bei der Begleitung durch Eltern an; Programme mit Elternbeteiligung senkten problematische Nutzung stärker. Dagegen: reine Elternangebote kaum belegt, sie erreichen vor allem Interessierte; Elternbildung tragen Länder und Kommunen, der Bund kann fördern.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=113', 'https://real.mtak.hu/222946', 'gemischt', '2026-10-07', false, true, 'blind'),
  (8599, 33, 18, 'BE', 'Medienkompetenz, reflektierter Umgang mit digitalen Technologien und Algorithmusverständnis werden fester Teil des Unterrichts.', '{3303}', 8389, 1, 3, null, 'Schulische Programme senkten problematische Nutzung deutlich, Bildschirmzeit kaum (Metaanalyse, 34 Studien, Verzerrung möglich). Allgemeine Medienbildung setzt nur indirekt an der Begleitung durch Eltern an.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=48', 'https://europepmc.org/article/MED/40549948', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8600, 33, 18, 'MV', 'Medien- und Demokratiebildung altersgerecht und fächerübergreifend ab der ersten Klasse im Unterricht verankern.', '{3303}', 8389, 1, 3, null, 'Schulische Programme senkten problematische Nutzung deutlich, Bildschirmzeit kaum (Metaanalyse, 34 Studien, Verzerrung möglich). Allgemeine Medienbildung setzt nur indirekt an der Begleitung durch Eltern an.', 'https://voltdeutschland.org/storage/assets-mv/pdf/haltungzeigen_wahlprogramm_voltmv_ltw26.pdf#page=7', 'https://europepmc.org/article/MED/40549948', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8601, 33, 18, 'ST', 'Medien- und Demokratiebildung ab Klasse 1 fächerübergreifend verankern, mit Vermittlung von Plattformlogiken und kritischer Medienkompetenz.', '{3303}', 8389, 1, 3, null, 'Schulische Programme senkten problematische Nutzung deutlich, Bildschirmzeit kaum (Metaanalyse, 34 Studien, Verzerrung möglich). Allgemeine Medienbildung setzt nur indirekt an der Begleitung durch Eltern an.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=30', 'https://europepmc.org/article/MED/40549948', 'gemischt', '2026-10-08', false, true, 'blind');

